using System;
using System.IO;
using System.Linq;
using System.Threading;
public static class StorageScopeTests {
 static void Check(bool value,string message){if(!value)throw new Exception(message);Console.WriteLine("PASS "+message);}
 static StorageSnapshot Snapshot(string root,string endpoint="local"){var s=new StorageSnapshot{Id=Guid.NewGuid().ToString("N"),DeviceId="local",Endpoint=endpoint,Root=root,IsLocal=true,Created=DateTime.UtcNow};s.Nodes.Add("0",new StorageNode{Id="0",Path=root,Directory=true,Name=root,Stamp=DateTime.UtcNow});return s;}
 public static int Main(){string fixture=Path.Combine(Path.GetTempPath(),"asterhub-scopes-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(fixture);try{
  var store=new StorageScopeStore(Path.Combine(fixture,"records"));var c=Snapshot(@"C:\");var d=Snapshot(@"D:\");c.Save(store.ScopeFile(c));store.Activate("local",store.ScopeFile(c));d.Save(store.ScopeFile(d));store.Activate("local",store.ScopeFile(d));
  Check(store.Records("local","local").Length==2,"C and D records coexist");Check(StorageSnapshot.Load(store.Find("local","local",c.Id)).Id==c.Id,"C remains readable after D");
  var reopened=new StorageScopeStore(Path.Combine(fixture,"records"));Check(reopened.ActiveFile("local")==store.ScopeFile(d),"selection survives restart");reopened.Activate("local",reopened.Find("local","local",c.Id));Check(StorageSnapshot.Load(reopened.ActiveFile("local")).Id==c.Id,"saved C can be selected without scanning");
  var c2=Snapshot(@"c:/");Check(store.ScopeFile(c2)==store.ScopeFile(c),"case and slash aliases share the same scope");c2.Save(store.ScopeFile(c2));Check(store.Records("local","local").Length==2&&store.Find("local","local",c.Id)==null&&store.Find("local","local",d.Id)!=null,"rescan replaces only the same scope");
  string kept=store.Find("local","local",c2.Id);var cancelled=Snapshot(@"C:\");using(var token=new CancellationTokenSource()){token.Cancel();try{cancelled.Save(store.ScopeFile(cancelled),token.Token);}catch(OperationCanceledException){}}Check(StorageSnapshot.Load(kept).Id==c2.Id,"cancelled rescan preserves previous complete record");
  var legacy=Snapshot(@"E:\");legacy.Save(store.LegacyFile("local"));Check(store.Find("local","local",legacy.Id)!=null,"legacy single-scope result remains selectable");Check(store.Records("local","changed-endpoint").Length==0,"records never leak across endpoints");
  var f1=Path.Combine(fixture,"one");var f2=Path.Combine(fixture,"two");Directory.CreateDirectory(f1);Directory.CreateDirectory(f2);File.WriteAllText(Path.Combine(f1,"a.txt"),"a");File.WriteAllText(Path.Combine(f2,"b.txt"),"bb");int published=0;var batch=new StorageScanJob(new Server{IsLocal=true},null,new[]{f1,f2});string jobId=batch.Id;batch.Run((s,t)=>{s.Save(store.ScopeFile(s),t);published++;return System.Threading.Tasks.Task.FromResult(0);}).GetAwaiter().GetResult();Check(batch.Status=="ready"&&published==2&&batch.Id==jobId,"batch publishes each scope with a stable controllable job id");
  var expectedFile=store.ScopeFile(Snapshot(f1,StorageSnapshot.EndpointFor(new Server{IsLocal=true})));var beforeFailure=StorageSnapshot.Load(expectedFile).Id;Directory.Move(f1,f1+"-held");var failed=new StorageScanJob(new Server{IsLocal=true},f1);failed.Run((s,t)=>{throw new Exception("failed root must not publish");}).GetAwaiter().GetResult();Check(failed.Status=="failed"&&StorageSnapshot.Load(expectedFile).Id==beforeFailure,"failed rescan preserves the previous result for the same scope");Directory.Move(f1+"-held",f1);
  int before=store.Records("local",StorageSnapshot.EndpointFor(new Server{IsLocal=true})).Length;var interrupted=new StorageScanJob(new Server{IsLocal=true},null,new[]{f1,f2});int commits=0;interrupted.Run((s,t)=>{s.Save(store.ScopeFile(s),t);commits++;interrupted.Cancel.Cancel();return System.Threading.Tasks.Task.FromResult(0);}).GetAwaiter().GetResult();Check(interrupted.Status=="cancelled"&&commits==1&&store.Records("local",StorageSnapshot.EndpointFor(new Server{IsLocal=true})).Length==before,"batch cancellation retains completed scopes and untouched scopes");return 0;
 }catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}finally{if(Path.GetDirectoryName(fixture)!=Path.GetTempPath().TrimEnd('\\'))throw new Exception("fixture escaped temp");Directory.Delete(fixture,true);}}
}
